module CanyonMapper (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [1:0] k,\n    input wire [15:0] x [0:7],\n    input wire [15:0] y [0:7],\n    output reg [15:0] side,\n    output reg done\n);\n\n    // States\n    localparam [2:0] IDLE            = 3'd0;\n    localparam [2:0] BOUNDING_BOX    = 3'd1;\n    localparam [2:0] INIT_BIN_SEARCH = 3'd2;\n    localparam [2:0] GENERATE_CANDIDATES = 3'd3;\n    localparam [2:0] CHECK_COMBOS    = 3'd4;\n    localparam [2:0] UPDATE_BOUNDS   = 3'd5;\n    localparam [2:0] FINISH          = 3'd6;\n\n    reg [2:0] state, next_state;\n\n    // Bounding box\n    reg [15:0] min_x, min_y, max_x, max_y;\n    reg [15:0] bb_width, bb_height;\n\n    // Binary search\n    reg [15:0] low, high, mid;\n    reg [15:0] best;\n    reg [5:0] cand_count;\n    reg found;\n\n    // Candidate squares\n    reg [15:0] cand_x [0:63];\n    reg [15:0] cand_y [0:63];\n    reg [7:0]  cand_masks [0:63];  // Coverage masks\n\n    // Combination check\n    reg [3:0] idx1, idx2, idx3;\n    reg [7:0] comb_mask;\n    reg [7:0] full_mask;\n\n    // Counters\n    integer i, j, m, p;\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            side <= 16'd0;\n            min_x <= 16'hFFFF;\n            min_y <= 16'hFFFF;\n            max_x <= 16'd0;\n            max_y <= 16'd0;\n            low <= 16'd0;\n            high <= 16'd0;\n            mid <= 16'd0;\n            best <= 16'd0;\n            cand_count <= 6'd0;\n            full_mask <= 8'd0;\n            for (i = 0; i < 64; i = i+1) begin\n                cand_x[i] <= 16'd0;\n                cand_y[i] <= 16'd0;\n                cand_masks[i] <= 8'd0;\n            end\n        end\n        else begin\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) next_state <= BOUNDING_BOX;\n                end\n\n                BOUNDING_BOX: begin\n                    min_x <= x[0];\n                    min_y <= y[0];\n                    max_x <= x[0];\n                    max_y <= y[0];\n\n                    for (i = 1; i < n; i = i+1) begin\n                        if (x[i] < min_x) min_x <= x[i];\n                        if (y[i] < min_y) min_y <= y[i];\n                        if (x[i] > max_x) max_x <= x[i];\n                        if (y[i] > max_y) max_y <= y[i];\n                    end\n                    next_state <= INIT_BIN_SEARCH;\n                end\n\n                INIT_BIN_SEARCH: begin\n                    bb_width  <= max_x - min_x;\n                    bb_height <= max_y - min_y;\n                    high <= (bb_width > bb_height) ? bb_width : bb_height;\n                    low <= 16'd0;\n                    best <= high;\n                    next_state <= (high > 0) ? GENERATE_CANDIDATES : FINISH;\n                end\n\n                GENERATE_CANDIDATES: begin\n                    mid <= (low + high + 1) >> 1;\n                    cand_count <= 6'd0;\n                    full_mask <= (1 << n) - 1;\n\n                    // Generate candidate squares\n                    for (i = 0; i < n; i = i+1) begin\n                        for (j = 0; j < n; j = j+1) begin\n                            cand_x[cand_count] <= x[i];\n                            cand_y[cand_count] <= y[j];\n                            cand_count <= cand_count + 6'd1;\n\n                            cand_x[cand_count] <= x[i] - mid;\n                            cand_y[cand_count] <= y[j];\n                            cand_count <= cand_count + 6'd1;\n\n                            cand_x[cand_count] <= x[i];\n                            cand_y[cand_count] <= y[j] - mid;\n                            cand_count <= cand_count + 6'd1;\n\n                            cand_x[cand_count] <= x[i] - mid;\n                            cand_y[cand_count] <= y[j] - mid;\n                            cand_count <= cand_count + 6'd1;\n                        end\n                    end\n\n                    next_state <= CHECK_COMBOS;\n                end\n\n                CHECK_COMBOS: begin\n                    found <= 1'b0;\n\n                    // Generate cover masks\n                    for (m = 0; m < cand_count; m = m+1) begin\n                        cand_masks[m] <= 8'd0;\n                        for (p = 0; p < n; p = p+1) begin\n                            if (x[p] >= cand_x[m] && x[p] <= (cand_x[m] + mid) &&\n                                y[p] >= cand_y[m] && y[p] <= (cand_y[m] + mid))\n                                cand_masks[m][p] <= 1'b1;\n                        end\n                    end\n\n                    // Check all k-combinations\n                    for (idx1 = 0; idx1 < cand_count; idx1 = idx1 + 1) begin\n                        if (k >= 2'd1) comb_mask <= cand_masks[idx1];\n                        if (comb_mask == full_mask) found <= 1'b1;\n\n                        if (k >= 2'd2) begin\n                            for (idx2 = 0; idx2 < cand_count; idx2 = idx2 + 1) begin\n                                comb_mask <= cand_masks[idx1] | cand_masks[idx2];\n                                if (comb_mask == full_mask) found <= 1'b1;\n\n                                if (k >= 2'd3) begin\n                                    for (idx3 = 0; idx3 < cand_count; idx3 = idx3 + 1) begin\n                                        comb_mask <= comb_mask | cand_masks[idx3];\n                                        if (comb_mask == full_mask) found <= 1'b1;\n                                    end\n                                end\n                            end\n                        end\n                    end\n\n                    next_state <= UPDATE_BOUNDS;\n                end\n\n                UPDATE_BOUNDS: begin\n                    if (found) begin\n                        best <= mid;\n                        high <= mid - 16'd1;\n                    end\n                    else begin\n                        low <= mid + 16'd1;\n                    end\n\n                    if (low <= high) begin\n                        next_state <= GENERATE_CANDIDATES;\n                    end\n                    else begin\n                        next_state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    side <= best;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule